SELECT , (SELECT COUNT(1) FROM TB_CPN_ISSUE I WHERE I.CPN_ID = C.CPN_ID AND I.USE_YN = 'Y') AS USE_CNT FROM TB_CPN C
AND C.CPN_NM LIKE '%' || #{CPN_NM} || '%' AND C.CPN_TYPE = #{CPN_TYPE} AND C.USE_YN = #{USE_YN}
ORDER BY C.REG_DT DESC, C.CPN_ID DESC

SELECT 
  FROM TB_CPN C
 WHERE C.CPN_ID = #{cpnId}

mapper.update:
UPDATE TB_CPN
   SET CPN_NM        = #{CPN_NM}
     , CPN_TYPE      = #{CPN_TYPE}
     , DC_VAL        = #{DC_VAL}
     , MAX_DC_AMT    = #{MAX_DC_AMT}
     , MIN_ORD_AMT   = NVL(#{MIN_ORD_AMT}, 0)
     , VALID_DAYS    = #{VALID_DAYS}
     , ISSUE_LMT_CNT = NVL(#{ISSUE_LMT_CNT}, 0)
     , ISSUE_STRT_DT = #{ISSUE_STRT_DT}
     , ISSUE_END_DT  = #{ISSUE_END_DT}
     , USE_YN        = NVL(#{USE_YN}, 'Y')
     , RMK           = #{RMK}
     , UPD_DT        = SYSDATE
     , UPD_ID        = #{USER_ID}
 WHERE CPN_ID = #{CPN_ID}

mapper.select:
SELECT * FROM (
  SELECT ROWNUM AS RNUM, A.* FROM (
    SELECT I.ISSUE_NO, I.CPN_ID, C.CPN_NM, C.CPN_TYPE, C.DC_VAL, I.MBR_ID, I.ISSUE_DT, I.EXP_DT,
           I.USE_YN, TO_CHAR(I.USE_DT, 'YYYY-MM-DD HH24:MI') AS USE_DT, I.ORD_NO, I.DC_AMT, I.ISSUE_TYPE,
           DECODE(I.USE_YN, 'Y', '사용', DECODE(SIGN(TO_NUMBER(TO_CHAR(SYSDATE, 'YYYYMMDD')) - TO_NUMBER(I.EXP_DT)), 1, '만료', '미사용')) AS ISSUE_STAT_NM
      FROM TB_CPN_ISSUE I
      JOIN TB_CPN C ON C.CPN_ID = I.CPN_ID

      AND I.CPN_ID = #{CPN_ID}
      AND I.MBR_ID = #{MBR_ID}
      AND I.ORD_NO = #{ORD_NO}
      AND I.USE_YN = #{USE_YN}
      AND I.ISSUE_DT >= #{FROM_DT}
      AND I.ISSUE_DT <= #{TO_DT}

     ORDER BY I.ISSUE_NO DESC
  ) A WHERE ROWNUM <= 1000
)

mapper.update:
UPDATE TB_CPN_ISSUE
   SET USE_YN = 'Y', USE_DT = SYSDATE, ORD_NO = #{ORD_NO}, DC_AMT = #{DC_AMT}
 WHERE ISSUE_NO = #{ISSUE_NO}
   AND USE_YN = 'N'

UPDATE TB_CPN_ISSUE
   SET USE_YN = 'N', USE_DT = NULL, ORD_NO = NULL, DC_AMT = 0
 WHERE ISSUE_NO = #{issueNo}
